import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";

// Replicate sortJson + deviceManifestHash from packages/server/src/worker-api/device-manifests.ts
function sortJson(value) {
  if (Array.isArray(value)) return value.map(sortJson);
  if (value === null || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.entries(value)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => [k, sortJson(v)])
  );
}

function hash(man) {
  const { manifest_hash: _ignored, ...payload } = man;
  for (const key of ["description","favicon_domain","auth_schema","actions_schema","options_schema"]) {
    if (payload[key] == null) delete payload[key];
  }
  return createHash("sha256").update(JSON.stringify(sortJson(payload))).digest("hex");
}

