            disclosureHeader(
                title: "Permissions",
                badge: "\(DevicePermissionKind.allCases.count - ungranted.count)/\(DevicePermissionKind.allCases.count)",
                expanded: $permissionsExpanded
            )

            if permissionsExpanded {
                // One permission per full-width row, status on the right.
