    private static func runJSON(_ args: [String], context: String?) async throws -> Data {
        let (stdout, _) = try await spawn(args, context: context)
        return stdout
    }

    @discardableResult
    private static func run(_ args: [String], context: String?) async throws -> Data {
        let (stdout, _) = try await spawn(args, context: context)
        return stdout
    }

    private static func spawnSync(_ args: [String], context: String?) throws -> Data {
        let (stdout, stderr, status) = try runProcess(args, context: context)
        guard status == 0 else {
            throw LobuCLIError.failed(
                exitCode: status,
                stderr: String(data: stderr, encoding: .utf8) ?? ""
            )
        }
        return stdout
    }

    private static func spawn(
        _ args: [String],
        context: String?
    ) async throws -> (stdout: Data, stderr: Data) {
        try await withCheckedThrowingContinuation { cont in
            DispatchQueue.global(qos: .userInitiated).async {
                do {
                    let (stdout, stderr, status) = try runProcess(args, context: context)
                    if status != 0 {
                        cont.resume(
                            throwing: LobuCLIError.failed(
                                exitCode: status,
                                stderr: String(data: stderr, encoding: .utf8) ?? ""
                            )
                        )
                    } else {
                        cont.resume(returning: (stdout, stderr))
                    }
                } catch let err as LobuCLIError {
                    cont.resume(throwing: err)
                } catch {
                    cont.resume(throwing: LobuCLIError.launch(error))
                }
            }
        }
    }

    private static func runProcess(
        _ args: [String],
        context: String?
    ) throws -> (stdout: Data, stderr: Data, exitCode: Int32) {
        guard let lobu = LocalLobuRunner.locateLobuCLI() else {
            throw LobuCLIError.cliNotFound
        }
        var fullArgs = args
        if let context, !context.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            fullArgs += ["--context", context]
        }

        let proc = Process()
        proc.executableURL = URL(fileURLWithPath: lobu)
        proc.arguments = fullArgs
        var env = ProcessInfo.processInfo.environment
        env["PATH"] = LocalLobuRunner.preferredPath(currentPath: env["PATH"] ?? "")
        proc.environment = env
        proc.standardInput = FileHandle.nullDevice

        let outPipe = Pipe()
        let errPipe = Pipe()
        proc.standardOutput = outPipe
        proc.standardError = errPipe

        do {
            try proc.run()
        } catch {
            throw LobuCLIError.launch(error)
        }
        proc.waitUntilExit()
        let stdout = outPipe.fileHandleForReading.readDataToEndOfFile()
        let stderr = errPipe.fileHandleForReading.readDataToEndOfFile()
        return (stdout, stderr, proc.terminationStatus)
