enum LobuCLIError: LocalizedError {
    case cliNotFound
    case launch(Error)
    case failed(exitCode: Int32, stderr: String)
    case decode(String)

    var errorDescription: String? {
        switch self {
        case .cliNotFound:
            return "The Lobu CLI isn't installed. Run `npm i -g @lobu/cli` (or `bun add -g @lobu/cli`), then try again."
        case let .launch(err):
            return "Couldn't run the Lobu CLI: \(err.localizedDescription)"
        case let .failed(code, stderr):
            let detail = stderr.trimmingCharacters(in: .whitespacesAndNewlines)
            return detail.isEmpty ? "Lobu CLI exited with code \(code)." : detail
        case let .decode(message):
            return "Couldn't read the Lobu CLI response: \(message)"
        }
    }
}

