// Bounded wait — `waitUntilExit()` blocks forever if the CLI hangs (a
// stuck token-refresh HTTP call, a hung network socket), which pins
// `isSyncing=true` in the caller and permanently kills the poll loop.
// Poll `isRunning` against a deadline; on timeout SIGTERM → grace →
// SIGKILL so the blocking read-to-EOF below returns promptly. Same
// technique as WatcherDispatcher.waitWithTimeout.
let deadline = Date().addingTimeInterval(timeout)
while proc.isRunning, Date() < deadline {
    Thread.sleep(forTimeInterval: 0.05)
}
if proc.isRunning {
    proc.terminate()
    Thread.sleep(forTimeInterval: TimeInterval(killGraceSeconds))
    if proc.isRunning { kill(proc.processIdentifier, SIGKILL) }
    // Let the reaped process flush its pipes so readDataToEndOfFile
    // doesn't itself block on a descriptor the kernel hasn't closed.
    proc.waitUntilExit()
}
